var numSmallerByFrequency = function(queries, words) {
    const frequency = (s) => {
        let smallest = 123;
        let count = 0;

        for (let i = 0; i < s.length; i++) {
            const character = s.charCodeAt(i);
            if (character < smallest) {
                smallest = character;
                count = 1;
            } else if (character === smallest) {
                count++;
