    let budget = newFlowers;

    // Complete the largest incomplete gardens first.
    for (let remaining = incomplete; remaining >= 0; remaining--) {
        if (budget < 0) break;

        const completeBeauty = (n - remaining) * full;
        if (remaining === 0) {
            answer = Math.max(answer, completeBeauty);
