    const memo = new Map();
    const base = n + 1;

    function solve(size, first, second) {
        if (first + second === size + 1) {
            return [1, 1];
        }

        // Reflect the row to merge symmetric states.
        if (first + second > size + 1) {
            [first, second] = [size + 1 - second, size + 1 - first];
        }

        const key = (size * base + first) * base + second;
        if (memo.has(key)) return memo.get(key);

        // Encode counts of winners preceding first and second.
        let states = new Set([0]);

        for (let left = 1, right = size; left <= right; left++, right--) {
            let winners;

            if (left === first || right === first) {
                winners = [first];
            } else if (left === second || right === second) {
                winners = [second];
            } else if (left === right) {
                winners = [left];
            } else {
                winners = [left, right];
            }

            const increments = new Set();
            for (const winner of winners) {
                increments.add(
                    (winner < first ? base : 0) +
                    (winner < second ? 1 : 0)
                );
            }

            const nextStates = new Set();
            for (const state of states) {
                for (const increment of increments) {
                    nextStates.add(state + increment);
                }
            }
            states = nextStates;
        }

        let earliest = Infinity;
        let latest = 0;
        const nextSize = Math.ceil(size / 2);

        for (const state of states) {
            const nextFirst = Math.floor(state / base) + 1;
            const nextSecond = state % base + 1;
            const result = solve(nextSize, nextFirst, nextSecond);

            earliest = Math.min(earliest, result[0] + 1);
            latest = Math.max(latest, result[1] + 1);
